        });
        var out = mod.runGateForPr(mod.githubBridgeIo(), 'o', 'n',
            { machineAuthor: BOT }, 12, { headRefOid: HEAD },
            function (l) { console.log(l); });
        assert.equal(out.held, true);
        assert.equal(out.holdPosted, true);
    });
});

