        // notes and cross-references also match).
        if (!pr) {
            var mergedList = scm.listPrs('merged');
            var byBranch = (Array.isArray(mergedList) ? mergedList : []).find(function (p) {
                return branchRe.test((p.head && p.head.ref) || '');
