            if (pr) {
                console.log('PR #' + pr.number + ' already merged for ' + ticketKey + ' — cleanup');
                try { github_remove_label({ owner: REPO.owner, repo: REPO.repo, number: issueNumber, label: approvedLabel }); } catch (e) {}
